#!/usr/bin/env node
// Exports the app's crayon icons (Android vector drawables `res/drawable/icon_*.xml`, generated by
// the app's tools/ui-assets/icons/draw_icons.py) to SVG for the extension, so both draw the same
// marks. Colours become currentColor; the selected forms keep their crayon wash (a clipped hatch at
// 38%). Usage: node scripts/export-crayon-icons.mjs <android res/drawable dir> [out dir]
import fs from 'node:fs';
import path from 'node:path';

const [source, outArg] = process.argv.slice(2);
if (!source) {
    console.error('usage: node scripts/export-crayon-icons.mjs <res/drawable> [assets/icons/crayon]');
    process.exit(1);
}
const out = path.resolve(outArg || 'assets/icons/crayon');
fs.mkdirSync(out, { recursive: true });

const attr = (text, name) => {
    const match = text.match(new RegExp(`android:${name}="([^"]*)"`));
    return match ? match[1] : null;
};
const title = name => name.replace(/_selected$/, '').replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());

function pathToSvg(node) {
    const d = attr(node, 'pathData');
    const stroke = attr(node, 'strokeColor');
    const fill = attr(node, 'fillColor');
    const parts = [`d="${d}"`];
    if (fill) parts.push('fill="currentColor"');
    if (stroke) {
        parts.push(`stroke-width="${attr(node, 'strokeWidth') || 1}"`);
        if (!fill) parts.push('fill="none"');
    } else parts.push('stroke="none"');
    const strokeAlpha = attr(node, 'strokeAlpha');
    if (strokeAlpha) parts.push(`stroke-opacity="${strokeAlpha}"`);
    const fillAlpha = attr(node, 'fillAlpha');
    if (fillAlpha) parts.push(`fill-opacity="${fillAlpha}"`);
    if (attr(node, 'fillType') === 'evenOdd') parts.push('fill-rule="evenodd"');
    return `<path ${parts.join(' ')}/>`;
}

// Player-only marks: the extension's own pages never draw a player, so they do not ship.
const PLAYER_ONLY = new Set(['back_10', 'forward_10', 'fullscreen', 'fullscreen_exit', 'pip', 'speed', 'volume', 'mute',
    'previous', 'next', 'shuffle', 'repeat_one', 'loop', 'queue', 'voice', 'replay', 'stop', 'pause', 'play', 'captions',
    'like', 'dislike']);

let written = 0;
for (const file of fs.readdirSync(source).filter(name => /^icon_.*\.xml$/.test(name)).sort()) {
    const xml = fs.readFileSync(path.join(source, file), 'utf8');
    const name = file.replace(/^icon_/, '').replace(/\.xml$/, '');
    if (PLAYER_ONLY.has(name.replace(/_selected$/, ''))) continue;
    const body = [];
    let clipIndex = 0;
    // Groups carry a clip-path (the wash's shape) and the hatch inside it.
    const tokens = xml.match(/<group>[\s\S]*?<\/group>|<path[\s\S]*?\/>/g) || [];
    for (const token of tokens) {
        if (token.startsWith('<group>')) {
            const clip = token.match(/<clip-path[\s\S]*?\/>/);
            const id = `w${clipIndex++}`;
            const inner = (token.match(/<path[\s\S]*?\/>/g) || []).map(pathToSvg).join('');
            body.push(`<clipPath id="${name}-${id}"><path d="${attr(clip[0], 'pathData')}"/></clipPath><g clip-path="url(#${name}-${id})">${inner}</g>`);
        } else body.push(pathToSvg(token));
    }
    const width = attr(xml, 'viewportWidth') || 24;
    const height = attr(xml, 'viewportHeight') || 24;
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="24" height="24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><title>${title(name)}</title>${body.join('')}</svg>\n`;
    // The extension has always called the funnel "filtertube_filter".
    const target = name.replace(/^filter(_selected)?$/, 'filtertube_filter$1');
    fs.writeFileSync(path.join(out, `${target}.svg`), svg);
    written++;
}
console.log(`wrote ${written} icons to ${out}`);
